static TCGTBCPUState bwm_get_tb_cpu_state(CPUState *cs)
{
    return (TCGTBCPUState){ .pc = cpu_env(cs)->pc, .flags = 0 };
}

static void bwm_cpu_synchronize_from_tb(CPUState *cs, const TranslationBlock *tb)
{
    tcg_debug_assert(!tcg_cflags_has(cs, CF_PCREL));
    cpu_env(cs)->pc = tb->pc;
}

static void bwm_restore_state_to_opc(CPUState *cs, const TranslationBlock *tb,
                                     const uint64_t *data)
{
    cpu_env(cs)->pc = data[0];
}

static bool bwm_cpu_exec_interrupt(CPUState *cs, int interrupt_request)
{
    return false;
}

static void bwm_cpu_do_interrupt(CPUState *cs)
{
    cs->exception_index = -1;
}

static bool bwm_cpu_tlb_fill(CPUState *cs, vaddr address, int size,
                             MMUAccessType access_type, int mmu_idx,
                             bool probe, uintptr_t retaddr)
{
    if (address >= BWM_ADDR_LIMIT) {
        if (probe) {
            return false;
        }
        bwm_fault(cs, retaddr, "access outside the memory map");
    }
    address &= TARGET_PAGE_MASK;
    tlb_set_page(cs, address, address, PAGE_READ | PAGE_WRITE | PAGE_EXEC,
                 mmu_idx, TARGET_PAGE_SIZE);
    return true;
}

static hwaddr bwm_cpu_get_phys_page_debug(CPUState *cs, vaddr addr)
{
    return addr;
}

static void bwm_cpu_reset_hold(Object *obj, ResetType type)
{
    CPUState *cs = CPU(obj);
    BWMCPUClass *mcc = BWM_CPU_GET_CLASS(obj);
    CPUBWMState *env = cpu_env(cs);

    if (mcc->parent_phases.hold) {
        mcc->parent_phases.hold(obj, type);
    }
    memset(env->regs, 0, sizeof(env->regs));
    env->pc = 0x0;
}

static void bwm_cpu_realizefn(DeviceState *dev, Error **errp)
{
    CPUState *cs = CPU(dev);
    BWMCPUClass *mcc = BWM_CPU_GET_CLASS(dev);
    Error *local_err = NULL;

    cpu_exec_realizefn(cs, &local_err);
    if (local_err != NULL) {
        error_propagate(errp, local_err);
        return;
    }
    qemu_init_vcpu(cs);
    cpu_reset(cs);
    mcc->parent_realize(dev, errp);
}

static ObjectClass *bwm_cpu_class_by_name(const char *cpu_model)
{
    return object_class_by_name(TYPE_BWM_CPU);
}

static void bwm_cpu_dump_state(CPUState *cs, FILE *f, int flags)
{
    CPUBWMState *env = cpu_env(cs);
    int i;

    qemu_fprintf(f, "pc  %016" PRIx64 "\n", env->pc);
    for (i = 0; i < BWM_NREGS; i++) {
        qemu_fprintf(f, "r%-2d %016" PRIx64 "%s", i, env->regs[i],
                     (i % 4) == 3 ? "\n" : "  ");
    }
}

