static void bwm_cpu_class_init(ObjectClass *oc, const void *data)
{
    DeviceClass *dc = DEVICE_CLASS(oc);
    CPUClass *cc = CPU_CLASS(oc);
    BWMCPUClass *mcc = BWM_CPU_CLASS(oc);
    ResettableClass *rc = RESETTABLE_CLASS(oc);

    device_class_set_parent_realize(dc, bwm_cpu_realizefn, &mcc->parent_realize);
    resettable_class_set_parent_phases(rc, NULL, bwm_cpu_reset_hold, NULL,
                                       &mcc->parent_phases);
    cc->class_by_name = bwm_cpu_class_by_name;
    cc->dump_state = bwm_cpu_dump_state;
    cc->set_pc = bwm_cpu_set_pc;
    cc->get_pc = bwm_cpu_get_pc;
    cc->sysemu_ops = &bwm_sysemu_ops;
    cc->tcg_ops = &bwm_tcg_ops;
}

